import "./heading.css";

export interface HeadingProps {
  text: string;
  level: "H1" | "H2" | "H3" | "H4";
  align: "left" | "center";
}

export function Heading({ text, level, align }: HeadingProps) {
  const Tag = level.toLowerCase() as "h1" | "h2" | "h3" | "h4";
  return (
    <div className="p1-heading p1-block" data-level={level} data-align={align}>
      <Tag className="p1-heading__text">{text}</Tag>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { Heading, type HeadingProps } from "./heading";
export type { HeadingProps };

export const HeadingBlock: ComponentConfig<HeadingProps> = {
  fields: {
    text: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "A section heading of 2-6 words. Plain text, sentence case, no trailing punctuation." },
    },
    level: {
      type: "select" as const,
      options: [
        { label: "H1", value: "H1" },
        { label: "H2", value: "H2" },
        { label: "H3", value: "H3" },
        { label: "H4", value: "H4" },
      ],
    },
    align: {
      type: "radio" as const,
      options: [
        { label: "Left", value: "left" },
        { label: "Center", value: "center" },
      ],
    },
  },
  defaultProps: { text: "A heading to anchor the section", level: "H2", align: "left" },
  render: Heading,
};

export const meta = defineMeta({
  title: 'Heading',
  description: 'Single H1–H4 heading element with left/center alignment; use to add a standalone section title.',
  categories: ["content"],
  published: true,
});

.p1-heading {
  padding-block: var(--p1-space-md);
}

.p1-heading[data-align="center"] .p1-heading__text {
  text-align: center;
}

.p1-heading[data-align="left"] .p1-heading__text {
  text-align: left;
}

.p1-heading__text {
  margin: 0;
  font-weight: var(--p1-weight-bold);
  line-height: var(--p1-leading-tight);
  letter-spacing: -0.025em;
  text-wrap: balance;
  color: var(--p1-fg-default);
}

.p1-heading[data-level="H1"] .p1-heading__text {
  font-size: var(--p1-text-4xl);
}

@media (width >= 48rem) {
  .p1-heading[data-level="H1"] .p1-heading__text {
    font-size: 3rem;
  }
}

.p1-heading[data-level="H2"] .p1-heading__text {
  font-size: var(--p1-text-3xl);
}

@media (width >= 48rem) {
  .p1-heading[data-level="H2"] .p1-heading__text {
    font-size: var(--p1-text-4xl);
  }
}

.p1-heading[data-level="H3"] .p1-heading__text {
  font-size: var(--p1-text-2xl);
}

@media (width >= 48rem) {
  .p1-heading[data-level="H3"] .p1-heading__text {
    font-size: var(--p1-text-3xl);
  }
}

.p1-heading[data-level="H4"] .p1-heading__text {
  font-size: var(--p1-text-xl);
}

